(function(root){
'use strict';const C=typeof module==='object'?require('./content.js'):root.HoorContent;
const stages=['dock','brief','route','fieldIntro','measure','extraIntro','bed','flow','float','summary','report','complete'];
const routes=[['الف','۴ کیلومتر','۳۰ تا ۹۰ سانتی‌متر','گل نرم','نیزار متراکم','آرام'],['ب','۶ کیلومتر','۱۲۰ تا ۱۵۰ سانتی‌متر','گل متراکم','نیزار پراکنده','آرام'],['ج','۵ کیلومتر','۸۰ تا ۲۴۰ سانتی‌متر','گل نرم و رسوبات','نیزار متوسط','متغیر']];
const depth=['۱۲۰','۱۳۵','۱۵۰'];
function create(){return {version:1,mission:'hoor02',stage:'dock',line:0,route:null,routeAttempts:0,points:[false,false,false],tool:false,observed:0,flowObserved:false,floatObserved:false,answers:{},journal:[],feedback:'',success:false,complete:false}}
function note(s,text){if(!s.journal.includes(text))s.journal.push(text)}
function go(s,stage){s.stage=stage;s.line=0;s.feedback='';s.success=false;if(stage==='route'){note(s,'دستور مأموریت: بررسی عمق آب و وضعیت بستر، مقایسه مسیرها، ثبت گزارش برای پورشریفی. نقشه و دفترچه دریافت شد.');note(s,'سه مسیر الف، ب و ج برای مقایسه ثبت شد.');routes.forEach(r=>note(s,'مسیر '+r.join('؛ ')))}if(stage==='complete'){s.complete=true;note(s,'اطلاعات اولیه برای بررسی بعدی ثبت شد؛ مرحله طراحی پل هنوز اجرا نشده است.')}}
function next(s){if(Array.isArray(C[s.stage])){if(s.line<C[s.stage].length-1)s.line++;else go(s,{dock:'brief',brief:'route',fieldIntro:'measure',extraIntro:'bed',report:'complete'}[s.stage]);return}if(s.stage==='route'&&s.success)go(s,'fieldIntro');else if(s.stage==='measure'&&s.success)go(s,'extraIntro');else if(s.stage==='summary')go(s,'report')}
function chooseRoute(s,value){if(s.stage!=='route'||!['a','b','c'].includes(value))return false;s.feedback=C.routeFeedback[value];s.success=value==='b';if(s.success){s.route='b';note(s,'مسیر ب برای بررسی میدانی انتخاب شد.')}else s.routeAttempts++;return s.success}
function measure(s,i){if(s.stage!=='measure'||!Number.isInteger(i)||i<0||i>2)return false;if(!s.tool){s.feedback='اول ابزار اندازه‌گیری را انتخاب کن';return false}s.points[i]=true;note(s,`نقطه ${i+1}: عمق ${depth[i]} سانتی‌متر؛ گل متراکم؛ نیزار پراکنده.`);s.tool=false;s.feedback=`نقطه ${i+1} بررسی شد: ${depth[i]} سانتی‌متر؛ گل متراکم؛ نیزار پراکنده.`;return true}
function answer(s,i){const q=C.quizzes[s.stage];if(!q||s.stage==='measure'&&!s.points.every(Boolean)||s.stage==='bed'&&s.observed<2||s.stage==='flow'&&!s.flowObserved||s.stage==='float'&&!s.floatObserved)return false;if(i!==q.correct){s.feedback=q.error;return false}s.answers[s.stage]=i;s.feedback='';if(s.stage==='measure'){s.success=true;s.feedback=C.measureSuccess;note(s,'عمق در نقاط بررسی‌شده از ۱۲۰ تا ۱۵۰ سانتی‌متر بود؛ بررسی‌های بیشتری برای تأیید لازم است.')}else if(s.stage==='bed'){note(s,'مقاومت بستر: فشار متوسط ۱۸ سانتی‌متر؛ فشار بیشتر ۲۶ سانتی‌متر. بستر تغییرشکل می‌دهد؛ محدودیت مهار شناورها باید بررسی شود.');go(s,'flow')}else if(s.stage==='flow'){note(s,'جریان آب: نشانگر ۴ متر طی ۲۰ ثانیه؛ سرعت تقریبی ۰٫۲ متر بر ثانیه.');go(s,'float')}else if(s.stage==='float'){note(s,'پایداری: مدل الف بدون مهار جانبی ۴۰ سانتی‌متر؛ مدل ب مهار از دو طرف ۸ سانتی‌متر؛ مدل ج مهار از یک طرف ۲۵ سانتی‌متر؛ مدل ب کمترین جابه‌جایی را دارد.');go(s,'summary')}return true}
function decode(raw){const s=JSON.parse(raw);if(!s||s.version!==1||s.mission!=='hoor02'||!stages.includes(s.stage)||!Number.isInteger(s.line)||s.line<0||s.line>=(Array.isArray(C[s.stage])?C[s.stage].length:1)||!Array.isArray(s.points)||s.points.length!==3||!s.points.every(x=>typeof x==='boolean')||!Array.isArray(s.journal)||s.journal.length>30||!s.journal.every(x=>typeof x==='string'&&x.length<2000)||!Number.isInteger(s.routeAttempts)||s.routeAttempts<0||![null,'b'].includes(s.route)||![0,1,2].includes(s.observed)||!['tool','success','complete','flowObserved','floatObserved'].every(k=>typeof s[k]==='boolean')||typeof s.feedback!=='string'||s.feedback.length>2000||!s.answers||typeof s.answers!=='object')throw Error('ذخیره نامعتبر');const index=stages.indexOf(s.stage);if(index>=3&&s.route!=='b'||index>=5&&(!s.points.every(Boolean)||s.answers.measure!==1)||index>=7&&s.answers.bed!==1||index>=8&&s.answers.flow!==0||index>=9&&s.answers.float!==1)throw Error('پیشرفت نامعتبر');s.complete=s.stage==='complete';return s}
const api={create,next,go,note,chooseRoute,measure,answer,decode,routes,depth,key:'sangarsazan.khaybar.hoor02.v1'};root.HoorModel=api;if(typeof module==='object')module.exports=api;
})(globalThis);
